mapper.select:
select EQUITY_CONF_DATE as equityConfDate, CHECK_TOTAL as checkTotal, ACCOUNT as account, PROD_REGIST_CODE as prodRegistCode, PROD_NAME as prodName, OPERATE_MODE as operateMode, VDATE as vdate, MDATE as mdate, IS_CONSIGN as isConsign, CHECK_MJ as checkMj, CHECK_SGAMT as checkSgamt, CHECK_SGQTY as checkSgqty, CHECK_SHQTY as checkShqty, CHECK_SHAMT as checkShamt from (
SELECT T.EQUITY_CONF_DATE, IF ( MJ_SUB.TOTAL_AMT = T.MJ_AMT AND CX_SUB.SGAMT = T.SG_AMT AND CX_SUB.SGQTY = T.SG_QTY AND CX_SUB.SHAMT = T.SH_AMT AND CX_SUB.SHQTY = T.SH_QTY, '01', '02' ) CHECK_TOTAL, T.ACCOUNT, MJ_SUB.PROD_REGIST_CODE, CPB.PROD_NAME, CPB.OPERATE_MODE, CPB.VDATE, CPB.MDATE, MJ_SUB.IS_CONSIGN, IF ( MJ_SUB.TOTAL_AMT = T.MJ_AMT, '01', '02' ) CHECK_MJ, IF ( CX_SUB.SGAMT = T.SG_AMT, '01', '02' ) CHECK_SGAMT, IF ( CX_SUB.SGQTY = T.SG_QTY, '01', '02' ) CHECK_SGQTY, IF ( CX_SUB.SHQTY = T.SH_QTY, '01', '02' ) CHECK_SHQTY, IF ( CX_SUB.SHAMT = T.SH_AMT, '01', '02' ) CHECK_SHAMT FROM ( SELECT T1.ACCOUNT, T1.EQUITY_CONF_DATE, SUM( IFNULL( T1.MJ_AMT, 0 ) ) AS MJ_AMT, SUM( IFNULL( T1.SG_QTY, 0 ) ) AS SG_QTY, SUM( IFNULL( T1.SG_AMT, 0 ) ) AS SG_AMT, SUM( IFNULL( T1.SH_QTY, 0 ) ) AS SH_QTY, SUM( IFNULL( T1.SH_AMT, 0 ) ) AS SH_AMT FROM ( SELECT B.ACCOUNT, C.MJ_AMT, B.EQUITY_CONF_DATE, SUM( IF ( B.BUSI_TYPE IN ( '02', '05', '14' ), IFNULL( SHARES, 0 ), 0 ) ) AS SG_QTY, SUM( IF ( B.BUSI_TYPE IN ( '02', '05', '14' ), IFNULL( AMOUNT_CNY, 0 ), 0 ) ) AS SG_AMT, SUM( IF ( B.BUSI_TYPE IN ( '03', '15', '16' ), IFNULL( SHARES, 0 ), 0 ) ) AS SH_QTY, SUM( IF ( B.BUSI_TYPE IN ( '03', '04', '05', '15', '16' ), IFNULL( AMOUNT_CNY, 0 ), 0 ) ) AS SH_AMT FROM CHB_EQUDET_SUB B, (SELECT A.ACCOUNT,-- A.EQUITY_CONF_DATE AS EQUITY_CONF_DATE, SUM( IF ( A.BUSI_TYPE IN ( '01' ), IFNULL( AMOUNT_CNY, 0 ), 0 ) ) AS MJ_AMT FROM CHB_EQUDET_SUB A WHERE A.BUSI_TYPE = '01' GROUP BY A.ACCOUNT) C WHERE B.BUSI_TYPE IN ( '02', '03', '04', '05', '14', '15', '16' ) and C.ACCOUNT = B.ACCOUNT GROUP BY B.ACCOUNT, B.EQUITY_CONF_DATE ) T1 GROUP BY T1.ACCOUNT, T1.EQUITY_CONF_DATE ) T LEFT JOIN ( SELECT CPRS.PROD_ID, CPRS.PROD_REGIST_CODE, CPRS.IS_CONSIGN, CPRS.TOTAL_AMT FROM CHB_PRD_RAISETOT_SUB CPRS ) MJ_SUB ON T.ACCOUNT = MJ_SUB.PROD_ID LEFT JOIN ( SELECT CPDS.PROD_ID, CPDS.MDATE, SUM( IFNULL( CPDS.PURCHASE_QTY, 0 ) ) AS SGQTY, SUM( IFNULL( CPDS.PURCHASE_QTY, 0 ) * IFNULL( CPDS.PRD_VALUE, 1 ) ) AS SGAMT, SUM( IFNULL( CPDS.REDEEM_QTY, 0 ) ) AS SHQTY, SUM( IFNULL( CPDS.REDEEM_QTY, 0 ) * IFNULL( CPDS.PRD_VALUE, 1 ) ) AS SHAMT FROM CHB_PRD_DEAL_SUB CPDS GROUP BY CPDS.PROD_ID, CPDS.MDATE ) CX_SUB ON T.ACCOUNT = CX_SUB.PROD_ID AND T.EQUITY_CONF_DATE = CX_SUB.MDATE LEFT JOIN CHB_PRD_BASEINFO CPB ON T.ACCOUNT = CPB.PROD_ID ) t
and date_format(EQUITY_CONF_DATE, '%Y-%m-%d') >= #{checkDateStart}
and date_format(EQUITY_CONF_DATE, '%Y-%m-%d') <= #{checkDateEnd}
and (ACCOUNT like concat('%', #{prod},'%') or PROD_NAME like concat('%', #{prod},'%'))
#{operateMode,jdbcType=VARCHAR}
#{checkResult,jdbcType=VARCHAR}
and date_format(VDATE, '%Y-%m-%d') >= #{vdateStart}
and date_format(VDATE, '%Y-%m-%d') <= #{vdateEnd}
and date_format(MDATE, '%Y-%m-%d') >= #{mdateStart}
and date_format(MDATE, '%Y-%m-%d') <= #{mdateEnd}
order by EQUITY_CONF_DATE desc,ACCOUNT asc
